use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let jobs = input.as_array().unwrap();
    let mut indices = Vec::new();
    let mut quantum = input.as_integer().unwrap();

    for (index, job) in jobs.iter().enumerate() {
        if job.is_u64() {
            indices.push(index as i64);
        } else {
            panic!("Invalid job type");
        }
    }

    if quantum <= 0 {
        panic!("Quantum must be positive");
    }

    indices.sort_unstable_by(|a, b| {
        if a == b {
            indices[a as usize] - indices[b as usize]
        } else {
            indices[a as usize].cmp(&indices[b as usize])
        }
    });

    indices.into_iter().map(|index| index as i64).collect()
}
